WITH flattened_attrs AS (SELECT id, currency, tier_prices, discounts, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers WHERE currency IN ('USD', 'THB')) SELECT id, currency, LAG(entry_price) OVER (PARTITION BY currency ORDER BY avg_tier_price ASC, id ASC) AS prev_entry_price, LAG(avg_tier_price) OVER (PARTITION BY currency ORDER BY avg_tier_price ASC, id ASC) AS prev_avg_tier_price, LEAD(avg_tier_price) OVER (PARTITION BY currency ORDER BY avg_tier_price ASC, id ASC) AS next_avg_tier_price, ROW_NUMBER() OVER (PARTITION BY currency ORDER BY avg_tier_price ASC, id ASC) AS seq_no FROM flattened_attrs WHERE avg_tier_price <= 27
